1|// Pure upload routing: which path a parsed book takes. Client-safe.
2|// The counts here are a hint only; the server enforces the real caps.
3|export const FREE_BOOK_MAX_WORDS = 50_000; // provisional, may change once we know the processing cost
4|export const WORDS_PER_PAGE = 250;
5|// Mirror of FREE_BOOKS_PER_PERSON in server/guard/quota.ts.
6|export const FREE_BOOKS_PER_DAY = 1;
7|
8|export function approxPages(words: number): number {
9|  return Math.max(1, Math.round(words / WORDS_PER_PAGE));
10|}
11|
12|export type UploadRoute = { kind: "free" } | { kind: "byok"; reason: "too_long" | "free_used" };
13|
14|// A long book needs its own key even when free books remain today.
15|export function uploadRoute(words: number, freeBooksToday: number): UploadRoute {
16|  if (words > FREE_BOOK_MAX_WORDS) return { kind: "byok", reason: "too_long" };
17|  if (freeBooksToday >= FREE_BOOKS_PER_DAY) return { kind: "byok", reason: "free_used" };
18|  return { kind: "free" };
19|}

