72|export class UploadValidationError extends Error {
73|  constructor(message = "invalid upload request") {
74|    super(message);
75|    this.name = "UploadValidationError";
76|  }
77|}
78|
79|// 128-bit random, base64url without padding (22 chars), prefixed so ids
80|// never collide with paragraph or scene ids.
81|export const UPLOAD_ID_RE = /^u-[A-Za-z0-9_-]{22}$/;
82|
83|const B64URL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
84|
85|export function newUploadId(): string {
86|  const bytes = new Uint8Array(16);
87|  globalThis.crypto.getRandomValues(bytes);
88|  let out = "u-";
89|  let bits = 0;
90|  let value = 0;
91|  for (const byte of bytes) {
92|    value = (value << 8) | byte;
93|    bits += 8;
94|    while (bits >= 6) {
95|      bits -= 6;
96|      out += B64URL[(value >> bits) & 63];
97|    }
98|  }
99|  if (bits > 0) out += B64URL[(value << (6 - bits)) & 63];
100|  return out;
101|}
102|
103|export function isUploadId(id: unknown): id is string {
104|  return typeof id === "string" && UPLOAD_ID_RE.test(id);
105|}
106|
107|export function parseUploadId(id: unknown): string {
108|  if (!isUploadId(id)) throw new UploadValidationError("bad upload id");
109|  return id;
110|}
