112|export interface UploadCreateBody {
113|  title: string;
114|  author: string | null;
115|  sections: RawSection[];
116|  turnstileToken?: string;
117|  friendCode?: string;
118|}
119|
120|// Optional friend code on the create body: checked server-side only,
121|// never logged or echoed back. Longer than this is rejected outright.
122|export const FRIEND_CODE_MAX_LEN = 64;
123|
124|function isRecord(json: unknown): json is Record<string, unknown> {
125|  return typeof json === "object" && json !== null && !Array.isArray(json);
126|}
127|
128|function isStringArray(value: unknown, maxItems: number, maxChars: number): value is string[] {
129|  return (
130|    Array.isArray(value) &&
131|    value.length <= maxItems &&
132|    value.every((t) => typeof t === "string" && t.length <= maxChars)
133|  );
134|}
135|
136|// Strict parse at the trust boundary: exact fields only, defensive caps on
137|// every list and string, so a bad client cannot push unbounded work in.
138|export function parseUploadCreate(json: unknown): UploadCreateBody {
139|  if (!isRecord(json)) throw new UploadValidationError();
140|  const keys = Object.keys(json).sort().join(",");
141|  const base = "author,sections,title";
142|  if (
143|    keys !== base &&
144|    keys !== "sections,title" &&
145|    keys !== `${base},turnstileToken` &&
146|    keys !== "sections,title,turnstileToken" &&
147|    keys !== "author,friendCode,sections,title" &&
148|    keys !== "friendCode,sections,title" &&
149|    keys !== "author,friendCode,sections,title,turnstileToken" &&
150|    keys !== "friendCode,sections,title,turnstileToken"
151|  ) {
152|    throw new UploadValidationError();
153|  }
154|  const title = json.title;
155|  if (typeof title !== "string" || title.trim().length === 0 || title.length > UPLOAD_MAX_TITLE_CHARS) {
156|    throw new UploadValidationError();
157|  }
158|  const author = json.author;
159|  if (author !== undefined && author !== null && (typeof author !== "string" || author.length > UPLOAD_MAX_TITLE_CHARS)) {
160|    throw new UploadValidationError();
161|  }
162|  const sections = json.sections;
163|  if (!Array.isArray(sections) || sections.length === 0 || sections.length > UPLOAD_MAX_SECTIONS) {
164|    throw new UploadValidationError();
165|  }
166|  const parsed: RawSection[] = sections.map((sec) => {
167|    if (!isRecord(sec)) throw new UploadValidationError();
168|    if (Object.keys(sec).sort().join(",") !== "blocks,docTitle,href,id,linear,navLabel,types") {
169|      throw new UploadValidationError();
170|    }
171|    if (typeof sec.id !== "string" || sec.id.length === 0 || sec.id.length > UPLOAD_MAX_TITLE_CHARS) {
172|      throw new UploadValidationError();
173|    }
174|    if (typeof sec.href !== "string" || sec.href.length > 2000) throw new UploadValidationError();
175|    if (typeof sec.linear !== "boolean") throw new UploadValidationError();
176|    if (!isStringArray(sec.types, 20, 100)) throw new UploadValidationError();
177|    for (const key of ["docTitle", "navLabel"] as const) {
178|      const value = sec[key];
179|      if (value !== null && (typeof value !== "string" || value.length > UPLOAD_MAX_TITLE_CHARS)) {
180|        throw new UploadValidationError();
181|      }
182|    }
183|    if (!Array.isArray(sec.blocks) || sec.blocks.length > UPLOAD_MAX_BLOCKS_PER_SECTION) {
184|      throw new UploadValidationError();
185|    }
186|    const blocks = sec.blocks.map((block) => {
187|      if (!isRecord(block)) throw new UploadValidationError();
188|      if (Object.keys(block).sort().join(",") !== "heading,text") throw new UploadValidationError();
189|      if (typeof block.text !== "string" || block.text.length > UPLOAD_MAX_BLOCK_CHARS) {
190|        throw new UploadValidationError();
191|      }
192|      if (typeof block.heading !== "boolean") throw new UploadValidationError();
193|      return { text: block.text, heading: block.heading };
194|    });
195|    return {
196|      id: sec.id,
197|      href: sec.href,
198|      linear: sec.linear,
199|      types: sec.types as string[],
200|      docTitle: sec.docTitle as string | null,
