248|// Marks the job failed, keeps what was really spent, and refunds the
249|// per-person quota only when nothing ran at all. Exactly once via the
250|// settle guard,
251|// best effort throughout: when the tally itself fails the reserve is kept,
252|// which is the conservative side. Settles before saving, so a kill between
253|// the two leaves at most an unsettled working job the cron still picks up.
254|// A job already done is never touched.
255|export async function failUploadJob(kv: KV, store: UploadStore, job: UploadJob, extra?: UploadUsage): Promise<void> {
256|  if (job.status === "done") return;
