264|  if (first && usage && isUsageZero(usage) && job.quotaIp && job.quotaAnon) {
265|    await refundDualQuota(kv, { ip: job.quotaIp, anon: job.quotaAnon });
266|  }
267|  job.status = "failed";
268|  if (usage) job.usage = usage;
269|  try {
270|    await saveUploadJob(kv, job);
271|  } catch {
272|    // Spend already settled above; a later fail or the cron re-saves this.
273|  }
