82|  let dailyTotal: number;
83|  try {
84|    dailyTotal = await kv.incrBy(dayKey, args.amountMicro);
85|    dailyLeft = true;
86|    await kv.expire(dayKey, DAILY_SPEND_TTL_SEC);
87|  } catch (e) {
